import {loadWebsiteSettings,applyWebsiteContent,websiteContent,serviceOverride} from './website-settings.js';
import {serviceDetails} from './service-details.js';
import {services,serviceCategories} from './services.js';
import {API,KEY} from './config.js';
const paths={arrow:'M7 17 17 7M7 7h10v10',right:'M5 12h14m-5-5 5 5-5 5',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',home:'m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9',grid:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',phone:'M7 3H4a1 1 0 0 0-1 1c0 10 7 17 17 17a1 1 0 0 0 1-1v-3l-5-2-2 2a14 14 0 0 1-7-7l2-2-2-5Z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',document:'M5 3h10l4 4v14H5zM14 3v5h5M8 12h8M8 16h6',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',chat:'M21 11a9 9 0 0 1-9 9H4l-3 2 2-6a9 9 0 1 1 18-5ZM7 10h10M7 14h6',leaf:'M20 3c-1 10-2 17-10 17a7 7 0 0 1-7-7c0-7 7-9 17-10ZM4 20 16 8',book:'M12 6C9 3 5 3 2 4v16c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-7-1-10 2ZM12 6v16',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',mail:'M3 5h18v14H3zM3 5l9 8 9-8',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 10h16',chart:'M4 3v18h17M8 16v-4M13 16V8M18 16V5',camera:'M3 7h4l2-3h6l2 3h4v14H3zM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4ZM8 12l3 3 5-6'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=v=>{try{const u=new URL(v,location.origin);return ['https:','http:'].includes(u.protocol)?esc(u.href):'';}catch{return ''}};
let wa='https://wa.me/6285185275605';
const external=(url,text,cls='button')=>`<a class="${cls}" href="${safeURL(url)}" target="_blank" rel="noopener">${esc(text)}${icon('arrow')}</a>`;
const fmtDate=(v,options={day:'numeric',month:'long',year:'numeric'})=>{const d=new Date(String(v).slice(0,10)+'T12:00:00');return Number.isNaN(d.getTime())?'Tanggal belum tersedia':new Intl.DateTimeFormat('id-ID',options).format(d)};
let data={pegawai_kua:[],kepala_kua:[]},announcements=[],annStatus='loading',stats=null,statsTotal=null,statsUpdated=null,statsState='idle',route='beranda',serviceCategory='all',serviceQuery='';
const main=document.getElementById('main'),dialog=document.getElementById('detailDialog');
async function api(table,query){const c=new AbortController(),timer=setTimeout(()=>c.abort(),14000);try{const r=await fetch(API+'/rest/v1/'+table+'?'+query,{headers:{apikey:KEY,Authorization:'Bearer '+KEY},signal:c.signal});if(!r.ok)throw new Error('Data belum tersedia');return await r.json();}finally{clearTimeout(timer)}}
const standardPath='assets/standar-pelayanan-kua-888-2026.pdf';
const featuredIds=['nikah','rekomendasi','buku','perubahan','bimwin','keluarga'];
const categoryName=id=>serviceCategories.find(c=>c.id===id)?.name||'';
function card(s,i,compact=false){return `<button type="button" class="catalog-card ${compact?'compact':''}" data-service="${s.id}"><span class="catalog-symbol">${icon(s.icon)}</span><span class="catalog-card-body">${compact?'':`<small>${categoryName(s.category)}</small>`}<h3>${s.name}</h3>${compact?'':`<p>${esc(s.desc)}</p>`}<span class="catalog-action">Lihat layanan ${icon('arrow')}</span></span></button>`}
function filteredServices(){const q=serviceQuery.trim().toLocaleLowerCase('id');return services.filter(s=>(serviceCategory==='all'||s.category===serviceCategory)&&(!q||(s.name+' '+s.official+' '+s.desc+' '+categoryName(s.category)).toLocaleLowerCase('id').includes(q)))}
function serviceGrid(){const rows=filteredServices();return `<div class="catalog-grid" id="serviceGrid">${rows.length?rows.map((s,i)=>card(s,i)).join(''):'<div class="empty" role="status">Layanan tidak ditemukan. Ubah kata pencarian atau pilih kelompok lain.</div>'}</div>`}
const searchMarkup=`<label class="search-box">${icon('search')}<input id="serviceSearch" type="search" placeholder="Cari layanan, misalnya buku nikah…" aria-label="Cari layanan"></label>`;
const banner=(title,desc,tag='KUA CIPEUNDEUY')=>`<section class="page-banner"><div class="container"><div class="breadcrumb"><a href="#beranda">Beranda</a><span>/</span><span>${title}</span></div><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${desc}</p></div></section>`;
const cta=()=>`<section class="cta"><div class="container"><div class="cta-inner"><div><h2>Masih ada yang ingin ditanyakan?</h2><p>Petugas KUA Cipeundeuy siap memberikan arahan untuk kebutuhan layanan Anda.</p></div>${external(wa,'Tanya melalui WhatsApp','button gold')}</div></div></section>`;
function home(){return `<section class="direct-home"><div class="container"><section class="home-statistics" aria-labelledby="homeStatsTitle"><div id="homeStatsContent">${homeStatsMarkup()}</div></section><section class="direct-panel"><div class="direct-heading"><div><span class="eyebrow">LAYANAN PUBLIK</span><h1>Layanan KUA Cipeundeuy</h1></div><a class="all-services-link" href="#layanan">Lihat Semua Layanan ${icon('right')}</a></div><div class="catalog-grid home-service-grid">${featuredIds.map((id,i)=>card(services.find(s=>s.id===id),i,true)).join('')}</div><a class="mobile-all-services" href="#layanan">Lihat Semua Layanan ${icon('right')}</a><div class="direct-source">Kepdirjen Bimas Islam Nomor 888 Tahun 2026</div></section><section class="home-announcement-panel" aria-labelledby="homeAnnouncementTitle"><div class="home-announcement-heading"><div><span class="eyebrow">INFORMASI MASYARAKAT</span><h2 id="homeAnnouncementTitle">Pengumuman kehendak nikah</h2></div><a class="text-link" href="#informasi?section=nikah">Lihat semua pengumuman ${icon('arrow')}</a></div><div id="homeAnnouncements" class="home-announcement-grid" aria-live="polite">${announcementMarkup(2)}</div></section><nav class="direct-information" aria-label="Informasi cepat"><a href="#nikah"><span class="direct-info-icon">${icon('book')}</span><span><strong>Panduan Nikah</strong><small>Pendaftaran & persiapan dokumen</small></span>${icon('arrow')}</a><a href="#informasi"><span class="direct-info-icon">${icon('bell')}</span><span><strong>Pengumuman Nikah</strong><small>Informasi periode berjalan</small></span>${icon('arrow')}</a><a href="#kontak"><span class="direct-info-icon">${icon('chat')}</span><span><strong>Hubungi Petugas</strong><small>Kontak & lokasi kantor</small></span>${icon('arrow')}</a></nav></div></section>`}
function announcementMarkup(limit=100){if(annStatus==='loading')return '<div class="loading" role="status">Memuat pengumuman periode berjalan…</div>';if(annStatus==='error')return '<div class="empty"><strong>Pengumuman belum dapat dimuat.</strong>Silakan coba kembali atau hubungi petugas.<br><button class="button outline" data-retry="announcements">Muat ulang</button></div>';if(!announcements.length)return '<div class="empty"><strong>Belum ada pengumuman dalam periode publikasi.</strong>Untuk informasi rencana akad nikah, silakan hubungi petugas KUA.</div>';return announcements.slice(0,limit).map((x,i)=>`<article class="announcement-row"><div class="date-tile"><small>${fmtDate(x.tanggal_akad,{month:'short'}).toUpperCase()}</small><strong>${fmtDate(x.tanggal_akad,{day:'numeric'})}</strong><small>${String(x.tanggal_akad).slice(0,4)}</small></div><div><h3>${esc(x.nama_suami)} <span style="color:#a38e5c">&</span><br>${esc(x.nama_istri)}</h3><p>${fmtDate(x.tanggal_akad,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p></div><button type="button" data-announcement="${i}" aria-label="Detail pengumuman ${esc(x.nama_suami)} dan ${esc(x.nama_istri)}">${icon('arrow')}</button></article>`).join('')}
function layanan(){return `<section class="catalog-banner"><div class="container"><div class="breadcrumb"><a href="#beranda">Beranda</a><span>/</span><span>Layanan</span></div><span class="eyebrow">STANDAR PELAYANAN KUA</span><h1>Semua layanan</h1><p>28 layanan · 7 kelompok · Kepdirjen Bimas Islam Nomor 888 Tahun 2026</p></div></section><section class="catalog-page"><div class="container"><div class="catalog-tools">${searchMarkup}<a class="standard-download" href="${standardPath}" target="_blank" rel="noopener">${icon('document')}Buka standar pelayanan ${icon('arrow')}</a></div><div class="category-filters" aria-label="Kelompok layanan"><button type="button" class="category-filter ${serviceCategory==='all'?'active':''}" data-service-category="all" aria-pressed="${serviceCategory==='all'}">Semua <span>28</span></button>${serviceCategories.map(c=>`<button type="button" class="category-filter ${serviceCategory===c.id?'active':''}" data-service-category="${c.id}" aria-pressed="${serviceCategory===c.id}">${c.name}<span>${services.filter(s=>s.category===c.id).length}</span></button>`).join('')}</div><div class="catalog-results" id="catalogResults" role="status">${filteredServices().length} layanan ditampilkan</div>${serviceGrid()}<div class="catalog-footnote">Nama ringkas digunakan agar mudah dicari. Nama layanan sesuai keputusan dan rujukan dokumen tersedia pada detail layanan.</div></div></section>`}
function updateCatalog(){const rows=filteredServices();const grid=document.getElementById('serviceGrid');if(grid)grid.innerHTML=rows.length?rows.map((s,i)=>card(s,i)).join(''):'<div class="empty" role="status">Layanan tidak ditemukan. Ubah kata pencarian atau pilih kelompok lain.</div>';const count=document.getElementById('catalogResults');if(count)count.textContent=rows.length+' layanan ditampilkan'}
function peopleMarkup(rows,isHead=false){if(!rows.length)return '<div class="empty">Data belum tersedia. Silakan muat ulang halaman atau hubungi petugas.</div>';return rows.map(x=>`<article class="person"><div class="person-img">${x.foto_url?`<img src="${safeURL(x.foto_url)}" alt="${esc(x.nama)}" loading="lazy">`:esc(x.nama.split(' ').filter(Boolean).slice(0,2).map(s=>s[0]).join(''))}</div><div class="person-body">${isHead?`<span class="period">${esc(x.masa)}</span>`:''}<h3>${esc(x.nama)}</h3><p>${esc(isHead?x.keterangan:x.jabatan)}</p></div></article>`).join('')}
function leadershipMarkup(){return data.kepala_kua.length?`<ol class="head-history">${data.kepala_kua.map((x,i)=>`<li><span class="history-index">${String(i+1).padStart(2,'0')}</span><div class="history-avatar">${x.foto_url?`<img src="${safeURL(x.foto_url)}" alt="${esc(x.nama)}" loading="lazy">`:icon('people')}</div><div><h3>${esc(x.nama)}</h3><p>${esc(x.keterangan)}</p></div><span class="history-period">${esc(x.masa)}</span></li>`).join('')}</ol>`:'<p class="empty">Data kepemimpinan belum tersedia.</p>'}
function profil(){return banner('Profil KUA Cipeundeuy','Pelayanan dan informasi keagamaan untuk masyarakat Kecamatan Cipeundeuy, Kabupaten Subang.','PROFIL INSTANSI')+`<section class="page-content profile-page"><div class="container"><nav class="profile-nav" aria-label="Bagian profil"><a href="#profil" data-jump="profileAbout">Tentang KUA</a><a href="#profil?section=sejarah" data-jump="profileHistory">Sejarah</a><a href="#profil?section=kepemimpinan" data-jump="profileLeadership">Kepemimpinan</a><a href="#pegawai">Pegawai ${icon('arrow')}</a></nav><div class="profile-intro" id="profileAbout"><div><span class="eyebrow">KUA CIPEUNDEUY · KABUPATEN SUBANG</span><h2>Dekat dengan masyarakat.<br>Hadir untuk melayani.</h2><p>Kantor Urusan Agama Kecamatan Cipeundeuy melayani kebutuhan keagamaan masyarakat di wilayah Kecamatan Cipeundeuy, Kabupaten Subang.</p><p>Melalui portal ini, masyarakat dapat menemukan persyaratan layanan nikah dan rujuk, bimbingan keluarga, kemasjidan, konsultasi syariah, serta layanan keagamaan lainnya.</p><div class="profile-actions"><a class="button" href="#layanan">Temukan layanan ${icon('arrow')}</a><a class="text-link" href="#pegawai">Kenali pegawai kami ${icon('arrow')}</a></div></div><aside class="profile-facts"><span class="eyebrow">IDENTITAS KANTOR</span><div><small>Nama instansi</small><strong>KUA Kecamatan Cipeundeuy</strong></div><div><small>Wilayah pelayanan</small><strong>Kecamatan Cipeundeuy, Kabupaten Subang</strong></div><div><small>Alamat kantor</small><strong>Jl. Raya Cipeundeuy No. 260, Kabupaten Subang</strong></div><a class="text-link" href="#kontak">Alamat & kontak ${icon('arrow')}</a></aside></div><section class="profile-history" id="profileHistory" aria-labelledby="historyTitle"><span class="eyebrow">SEJARAH SINGKAT</span><h2 id="historyTitle">Perjalanan pelayanan KUA.</h2><div class="timeline">${[['1986','KUA Perwakilan','Berawal sebagai KUA perwakilan yang masih melekat pada KUA Kalijati.'],['1994','KUA Definitif','Menjadi KUA definitif dengan kepala pertama Drs. H. Sahyat Sobarna.'],['2001','Tanah Wakaf','Catatan sejarah memuat tanah wakaf di Jl. Raya Cipeundeuy No. 260 yang kemudian menjadi lokasi pembangunan gedung KUA.']].map(x=>`<article><span class="year">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></section><section class="leadership" id="profileLeadership"><div class="section-head"><div><span class="eyebrow">RIWAYAT KEPEMIMPINAN</span><h2>Kepala KUA dari masa ke masa.</h2></div><a class="text-link" href="#pegawai">Pegawai KUA ${icon('arrow')}</a></div><div id="leadershipGrid">${leadershipMarkup()}</div></section><section class="profile-visit"><div>${icon('pin')}<span class="eyebrow">KUNJUNGI KANTOR KAMI</span><h2>Perlu bantuan langsung?</h2><p>Jl. Raya Cipeundeuy No. 260, Kabupaten Subang.</p><p class="profile-hours">Senin–Kamis: 07.30–16.00 WIB · Jumat: 07.30–16.30 WIB</p></div><div class="profile-visit-actions"><a class="button" href="#kontak">Lihat kontak & lokasi ${icon('arrow')}</a>${external(wa,'Hubungi melalui WhatsApp','button outline')}</div></section></div></section>`}

function pegawai(){return banner('Pegawai KUA Cipeundeuy','Kenali jajaran pegawai yang mendukung pelayanan keagamaan bagi masyarakat.','TIM PELAYANAN')+`<section class="page-content"><div class="container"><div class="people-grid" id="employeeGrid">${peopleMarkup(data.pegawai_kua)}</div></div></section>`+cta()}
function infoTabs(active){return `<nav class="page-nav" aria-label="Informasi KUA"><a class="tab ${active==='informasi'?'active':''}" href="#informasi">Pengumuman kehendak nikah</a><a class="tab ${active==='data'?'active':''}" href="#data">Statistik pernikahan</a></nav>`}
function informasi(){const notices=websiteContent().notices;return banner('Informasi & pengumuman','Pemberitahuan pelayanan dan pengumuman nikah KUA Cipeundeuy.','INFORMASI MASYARAKAT')+`<section class="page-content"><div class="container"><nav class="information-links" aria-label="Bantuan informasi"><a href="#faq">${icon('chat')}<span><strong>Pertanyaan umum</strong><small>Jawaban seputar layanan KUA</small></span>${icon('arrow')}</a><a href="#privasi">${icon('document')}<span><strong>Kebijakan privasi</strong><small>Penggunaan dan perlindungan data</small></span>${icon('arrow')}</a><a href="#kontak">${icon('phone')}<span><strong>Hubungi petugas</strong><small>Konfirmasi informasi pelayanan</small></span>${icon('arrow')}</a></nav><section class="public-info-block"><span class="eyebrow">PEMBERITAHUAN RESMI</span><h2>Pengumuman layanan</h2>${notices.length?notices.map(x=>`<article class="service-notice"><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p></article>`).join(''):'<p class="muted">Belum ada pengumuman layanan yang diterbitkan. Untuk konfirmasi jadwal dan pelayanan, silakan <a href="#kontak">hubungi petugas</a>.</p>'}</section><section class="info-layout" id="marriageAnnouncements"><h2 class="announcement-heading">Semua pengumuman kehendak nikah</h2><div id="allAnnouncements" class="announcement-list">${announcementMarkup()}</div><p class="preview-note">Daftar pengumuman aktif sesuai pengaturan publikasi dan tanggal akad. Hubungi petugas jika ada informasi yang perlu dikoreksi.</p></section></div></section>`}
function faqPage(){const items=[['Apakah pengunjung harus login?','Tidak. Informasi layanan, panduan nikah, dan pengumuman dapat dibaca tanpa login. Login digunakan oleh petugas yang memiliki akses pengelolaan.'],['Bagaimana mengetahui persyaratan suatu layanan?','Buka halaman Layanan, pilih layanan yang dibutuhkan, lalu baca persyaratan dan prosedurnya. Konfirmasikan keadaan khusus kepada petugas sebelum datang.'],['Bagaimana memulai pendaftaran nikah?','Baca Panduan Nikah untuk mempersiapkan dokumen dan alur pendaftaran. Gunakan tautan SIMKAH yang tersedia pada panduan dan konfirmasikan berkas serta jadwal dengan petugas KUA.'],['Bagaimana mengetahui biaya dan waktu pelayanan?','Rincian biaya dan waktu tersedia pada masing-masing layanan. Hubungi petugas untuk memastikan ketentuan yang sesuai dengan kebutuhan Anda.'],['Kapan kantor melayani masyarakat?','Senin–Kamis pukul 07.30–16.00 WIB dan Jumat pukul 07.30–16.30 WIB. Perhatikan pengumuman layanan untuk perubahan jadwal atau hari libur.'],['Bagaimana mengikuti bimbingan perkawinan?','Hubungi petugas KUA untuk informasi jadwal, tempat, persyaratan peserta, dan cara mengikuti bimbingan perkawinan.'],['Mengapa pengumuman nikah tertentu belum terlihat?','Pengumuman mengikuti pengaturan publikasi, kelengkapan data, dan tanggal akad. Tidak munculnya pengumuman bukan bukti status pendaftaran; konfirmasikan kepada petugas.'],['Bagaimana memperbaiki informasi pengumuman yang keliru?','Hubungi petugas melalui kanal resmi dan jelaskan bagian yang perlu diperiksa. Hindari mengirim NIK atau foto dokumen pribadi melalui ruang publik.'],['Apakah data arsip pernikahan dapat dicari oleh pengunjung?','Pencarian arsip dikelola oleh petugas yang berwenang. Pengunjung dapat melihat statistik agregat dan pengumuman yang dipublikasikan. Untuk kebutuhan dokumen atau konfirmasi arsip, hubungi kantor.']];return banner('Pertanyaan umum','Jawaban singkat untuk membantu Anda menggunakan layanan KUA.','PUSAT BANTUAN')+`<section class="page-content"><div class="container reading-page"><div class="faq">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><div class="help-strip"><h2>Masih memerlukan bantuan?</h2><p>Petugas dapat membantu memeriksa kebutuhan layanan Anda.</p><a class="button" href="#kontak">Hubungi petugas ${icon('arrow')}</a> <a class="text-link" href="#nikah">Panduan nikah</a></div></div></section>`}
function privacyPage(){return banner('Kebijakan privasi','Informasi penggunaan data pada portal KUA Cipeundeuy.','TRANSPARANSI DATA')+`<section class="page-content"><article class="container reading-page privacy-copy"><p class="preview-note">Terakhir diperbarui: 12 November 2026</p><h2>Ruang lingkup</h2><p>Kebijakan ini menjelaskan penggunaan data pada website KUA Cipeundeuy. Untuk pertanyaan tentang data atau layanan, hubungi petugas melalui halaman <a href="#kontak">Kontak</a>.</p><h2>Data yang digunakan</h2><p>Pengunjung dapat membaca informasi publik tanpa membuat akun. Situs menampilkan informasi layanan, profil petugas, statistik pernikahan dalam bentuk agregat, serta pengumuman nikah yang dipublikasikan oleh petugas. Detail pengumuman dapat memuat nama calon pengantin, foto, tanggal, dan lokasi akad.</p><p>Dalam pengelolaan layanan, petugas yang berwenang dapat mengolah data arsip pernikahan dan data akun admin. Data arsip tidak disediakan sebagai pencarian publik. Jika Anda menghubungi kantor melalui WhatsApp, telepon, atau email, informasi yang Anda sampaikan digunakan untuk menanggapi kebutuhan layanan.</p><h2>Tujuan penggunaan</h2><p>Data digunakan untuk penyampaian informasi pelayanan, publikasi pengumuman nikah, penyajian statistik agregat, serta pengelolaan arsip dan akses petugas. Jangan mengirimkan kata sandi, kode OTP, atau dokumen pribadi melalui kolom atau kanal publik.</p><h2>Penyimpanan dan akses</h2><p>Website dihosting melalui GitHub Pages dan menggunakan Supabase untuk layanan data serta autentikasi. Pengelolaan data dibatasi melalui akun petugas dan izin akses database. Akses teknis ke layanan hosting dan database dapat melibatkan pemrosesan informasi koneksi, seperti alamat IP, sesuai pengoperasian layanan tersebut.</p><p>Periode publikasi pengumuman mengikuti pengaturan dan tanggal akad. Pengumuman yang tidak lagi tampil belum tentu telah dihapus dari arsip. Untuk informasi masa simpan arsip dan penanganan data tertentu, hubungi petugas KUA.</p><h2>Penyimpanan pada perangkat</h2><p>Pilihan mode terang atau gelap disimpan di browser pengunjung. Sesi login admin juga menggunakan penyimpanan lokal browser agar petugas tetap dikenali saat mengelola situs. Setelah memakai perangkat bersama, lakukan logout. Kode situs ini tidak memasang pelacak iklan atau analitik tambahan.</p><h2>Tautan ke layanan lain</h2><p>Tautan SIMKAH, WhatsApp, Google Maps, dan media sosial membuka layanan pihak lain. Data yang Anda berikan di layanan tersebut mengikuti kebijakan masing-masing penyedia.</p><h2>Koreksi dan pertanyaan data</h2><p>Jika informasi tentang Anda tidak tepat atau Anda ingin menanyakan publikasi, akses, maupun penghapusan data, hubungi petugas KUA melalui kanal resmi. Petugas dapat meminta verifikasi identitas seperlunya untuk memeriksa permintaan dan ketentuan administrasi arsip yang berlaku. Jangan mengirim identitas lengkap sebelum memperoleh arahan petugas.</p><h2>Pembaruan kebijakan</h2><p>Kebijakan dapat diperbarui ketika fitur atau pengelolaan data berubah. Versi terbaru ditampilkan pada halaman ini.</p><a class="button" href="#kontak">Hubungi KUA Cipeundeuy ${icon('arrow')}</a></article></section>`}

function statsBars(){const years=Object.keys(stats||{}).sort((a,b)=>Number(a)-Number(b)),max=Math.max(...Object.values(stats||{}),1);if(!years.length)return '<div class="empty">Belum ada arsip dengan tahun indeks.</div>';return `<div class="annual-scroll" tabindex="0" role="region" aria-label="Grafik jumlah arsip pernikahan per tahun; geser untuk melihat seluruh tahun"><div class="annual-bars">${years.map(y=>`<div class="annual-column" role="img" aria-label="${y}: ${stats[y].toLocaleString('id-ID')} arsip"><span class="annual-value">${stats[y].toLocaleString('id-ID')}</span><div class="annual-bar-slot"><div class="annual-bar ${y===years.at(-1)?'latest':''}" style="height:${Math.max(2,stats[y]/max*100)}%" title="${y}: ${stats[y].toLocaleString('id-ID')} arsip"></div></div><span class="annual-year">${y}</span></div>`).join('')}</div></div>`}
function homeStatsMarkup(){const heading=`<div class="home-stats-heading"><div><span class="eyebrow">DATA PERNIKAHAN</span><h2 id="homeStatsTitle">Pernikahan dari tahun ke tahun</h2></div><a class="text-link" href="#data">Lihat rincian ${icon('arrow')}</a></div>`;if(statsState==='error')return heading+'<div class="stats-unavailable">Statistik belum dapat dimuat. <button type="button" data-retry="stats">Muat ulang</button></div>';if(!stats)return heading+'<div class="loading" role="status">Memuat data pernikahan…</div>';const years=Object.keys(stats).sort((a,b)=>Number(a)-Number(b)),latest=years.at(-1);return heading+`<div class="home-stats-summary"><div><small>Total arsip digital</small><strong>${Number(statsTotal).toLocaleString('id-ID')}</strong></div><div><small>Periode tahun indeks</small><strong>${years.length?years[0]+'–'+latest:'—'}</strong></div><div><small>Arsip tahun ${latest||'terakhir'}</small><strong>${latest?stats[latest].toLocaleString('id-ID'):'—'}</strong></div><span class="stats-live"><span class="dot"></span>Data terbaru</span></div>${statsBars()}<p class="annual-note">Arsip tanpa tahun indeks tidak masuk grafik. Data tahun berjalan belum mencakup satu tahun penuh.</p><span class="annual-scroll-note">Geser grafik untuk melihat tahun lainnya ↔</span>`}
function statsContent(){if(statsState==='loading')return '<div class="loading" role="status">Memuat statistik arsip pernikahan…</div>';if(statsState==='error')return '<div class="empty"><strong>Statistik belum dapat ditampilkan.</strong>Silakan coba memuat kembali data.<br><button class="button outline" data-retry="stats">Coba muat kembali</button></div>';if(!stats)return '';const years=Object.keys(stats).sort((a,b)=>Number(a)-Number(b)),indexed=Object.values(stats).reduce((a,b)=>a+b,0);return `<div class="stats-grid"><article class="stat"><small>Total arsip digital</small><strong>${Number(statsTotal).toLocaleString('id-ID')}</strong><span>Total arsip pada sumber statistik publik</span></article><article class="stat"><small>Periode tahun indeks</small><strong>${years.length?years[0]+'–'+years.at(-1):'—'}</strong><span>${indexed.toLocaleString('id-ID')} arsip memiliki tahun indeks</span></article></div><div class="chart-panel"><h2>Arsip pernikahan per tahun</h2><p>Grafik mengikuti tahun indeks arsip, termasuk data tahun berjalan yang belum mencakup satu tahun penuh.</p>${statsBars()}</div><details class="annual-table"><summary>Lihat tabel jumlah per tahun</summary><table><caption>Jumlah arsip pernikahan menurut tahun indeks</caption><thead><tr><th scope="col">Tahun</th><th scope="col">Jumlah arsip</th></tr></thead><tbody>${years.map(y=>`<tr><th scope="row">${y}</th><td>${stats[y].toLocaleString('id-ID')}</td></tr>`).join('')}</tbody></table></details>`}
function dataPage(){return banner('Statistik pernikahan','Ringkasan arsip pencatatan nikah berdasarkan tahun indeks yang dapat diakses.','DATA LAYANAN')+`<section class="page-content"><div class="container">${infoTabs('data')}<div id="statsContent">${statsContent()}</div><div class="private-note"><strong>${icon('shield').replace('<svg','<svg style="width:16px;height:16px;vertical-align:middle;margin-right:7px"')}Privasi data pernikahan</strong>Pencarian berdasarkan nama dan nomor akta tidak tersedia untuk pengunjung umum. Permohonan terkait arsip dilayani melalui petugas yang berwenang.</div></div></section>`}
function kontak(){return banner('Kontak & lokasi','Gunakan kanal resmi untuk bertanya, berkonsultasi, atau merencanakan kunjungan Anda.','MARI TERHUBUNG')+`<section class="page-content"><div class="container"><div class="contact-layout"><div><h2>Kami siap memberikan arahan.</h2><div class="contact-list"><a href="${wa}" target="_blank" rel="noopener">${icon('chat')}<span><small>WhatsApp layanan</small><strong>0851-8527-5605</strong></span></a><a href="tel:0260713214">${icon('phone')}<span><small>Telepon kantor</small><strong>(0260) 713214</strong></span></a><a href="mailto:kuacipeundeuy20@gmail.com">${icon('mail')}<span><small>Email</small><strong>kuacipeundeuy20@gmail.com</strong></span></a><a href="https://www.instagram.com/kua.cipeundeuy.subang/" target="_blank" rel="noopener">${icon('camera')}<span><small>Instagram</small><strong>@kua.cipeundeuy.subang</strong></span></a></div><section class="office-hours" aria-labelledby="officeHoursTitle"><span class="eyebrow">RENCANAKAN KUNJUNGAN</span><h3 id="officeHoursTitle">Jam pelayanan kantor</h3><dl><div><dt>Senin–Kamis</dt><dd>07.30–16.00 WIB</dd></div><div><dt>Jumat</dt><dd>07.30–16.30 WIB</dd></div></dl><p>Untuk layanan yang memerlukan jadwal khusus, hubungi petugas sebelum berkunjung.</p></section></div><aside class="location-panel"><div class="location-pattern" aria-hidden="true"></div><div><span class="pin">${icon('pin')}</span><span class="eyebrow">LOKASI KANTOR</span><h3>KUA Cipeundeuy</h3><p>Jl. Raya Cipeundeuy No. 260,<br>Kabupaten Subang</p>${external('https://www.google.com/maps/search/?api=1&query=Kantor+Urusan+Agama+Cipeundeuy+Subang','Buka petunjuk arah')}</div></aside></div><section class="faq"><h2>Pertanyaan yang sering diajukan.</h2><details><summary>Bisakah saya bertanya melalui WhatsApp terlebih dahulu?</summary><p>Bisa. Sampaikan kebutuhan layanan secara singkat melalui nomor WhatsApp resmi KUA Cipeundeuy agar petugas dapat memberikan arahan.</p></details><details><summary>Di mana kantor KUA Cipeundeuy?</summary><p>Kantor berada di Jl. Raya Cipeundeuy No. 260, Kabupaten Subang. Gunakan tombol petunjuk arah untuk membuka lokasi melalui Google Maps.</p></details><details><summary>Kapan saya dapat datang ke kantor?</summary><p>Jam pelayanan Senin–Kamis pukul 07.30–16.00 WIB dan Jumat pukul 07.30–16.30 WIB. Untuk jadwal khusus, konfirmasikan melalui petugas.</p></details><details><summary>Apa yang perlu disiapkan sebelum datang?</summary><p>Pilih layanan pada halaman Layanan untuk membaca persyaratan dan prosedurnya. Jika masih ada pertanyaan, hubungi petugas melalui WhatsApp.</p><a class="text-link" href="#layanan">Lihat semua layanan ${icon('arrow')}</a></details></section></div></section>`}
