function render(scroll=true){let requested=location.hash.slice(1).split('?')[0]||'beranda';route=Object.hasOwn(renderers,requested)?requested:'beranda';const params=new URLSearchParams(location.hash.split('?')[1]||'');if(route==='layanan'){const group=params.get('group')||'all';serviceCategory=serviceCategories.some(x=>x.id===group)?group:'all';serviceQuery='';}main.innerHTML=renderers[route]();applyWebsiteContent(main);document.title=({beranda:'KUA Cipeundeuy — Melayani dengan Hati',layanan:'Layanan masyarakat',nikah:'Panduan nikah',profil:'Profil KUA',pegawai:'Pegawai KUA',informasi:'Informasi & pengumuman',faq:'Pertanyaan umum',privasi:'Kebijakan privasi',data:'Statistik pernikahan',kontak:'Kontak & lokasi'}[route])+(route==='beranda'?'':' — KUA Cipeundeuy');hydrateIcons(main);const search=document.getElementById('serviceSearch');if(search)search.value=serviceQuery;document.querySelectorAll('.desktop-nav a,.bottom-nav a').forEach(a=>{let dest=a.hash.slice(1);a.classList.toggle('active',dest===route||(['data','faq','privasi'].includes(route)&&dest==='informasi')||(route==='pegawai'&&dest==='profil'));if(a.classList.contains('active'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const period=document.getElementById('announcementPeriod');if(period)period.textContent=new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(new Date());closeMenu();if(scroll)window.scrollTo({top:0,behavior:'instant'});if((route==='data'||route==='beranda')&&statsState==='idle')loadStats();sectionRoute(params);}
