function openDialog(html){document.getElementById('dialogContent').innerHTML=html;hydrateIcons(dialog);if(!dialog.open)dialog.showModal()}
function detailParagraphs(items){return items.map(x=>`<p>${esc(x)}</p>`).join('')}
function openService(id){const s=services.find(x=>x.id===id);if(!s)return;const d=serviceDetails[id];const sections=[['requirements','Persyaratan'],['procedure','Prosedur pelayanan'],['duration','Waktu penyelesaian'],['fee','Biaya / tarif'],['output','Hasil layanan']];openDialog(`<span class="eyebrow">${esc(categoryName(s.category))}</span><h2 id="dialogTitle">${esc(s.name)}</h2><p>${esc(s.desc)}</p><div class="standard-detail"><small>STANDAR PELAYANAN</small><strong>${esc(s.official)}</strong><span>${d.visitOffice?'Pelayanan langsung di kantor KUA Cipeundeuy':`Kepdirjen Bimas Islam Nomor 888 Tahun 2026 · halaman ${d.page}`}</span></div>${d.visitOffice?`<div class="service-review"><h3>Datang langsung ke kantor KUA</h3><p>Untuk layanan keterangan status pernikahan, silakan datang langsung ke KUA Cipeundeuy. Petugas akan menjelaskan persyaratan dan membantu proses pelayanan.</p><a class="text-link" href="#kontak" data-close-service>Lihat alamat dan lokasi kantor ${icon('arrow')}</a></div>`:d.needsConfirmation?`<div class="service-review"><h3>Konfirmasi persyaratan kepada petugas</h3><p>Uraian pada bagian ini dalam dokumen sumber tampak tidak sesuai dengan judul layanan. Hubungi petugas untuk memastikan persyaratan, prosedur, waktu, biaya, dan hasil layanan sebelum mengajukan permohonan.</p></div>`:`<div class="service-detail-sections">${sections.map(([key,label],i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${label}</summary><div class="service-detail-body">${detailParagraphs(d[key])}</div></details>`).join('')}</div><p class="detail-source-note">${esc(d.sourceNote||'Rincian ditranskripsikan dari dokumen standar pelayanan.')} Persyaratan khusus berlaku sesuai kondisi pemohon. Konfirmasikan kelengkapan berkas dan jadwal kepada petugas.</p>`}<div class="dialog-actions">${d.visitOffice?'':`<a class="button" href="${standardPath}#page=${d.page}" target="_blank" rel="noopener">Lihat dokumen sumber ${icon('arrow')}</a>`}${external(wa+'?text='+encodeURIComponent('Assalamualaikum, saya ingin bertanya mengenai layanan '+s.name+'.'),'Tanya petugas','button outline')}${s.id==='nikah'?external('https://simkah4.kemenag.go.id/','Daftar melalui SIMKAH','button outline'):''}</div>`)}

// Tautan pengumuman memakai tanggal dan nama, bukan posisi dalam daftar.
function announcementKey(x){return [String(x.tanggal_akad||'').slice(0,10),String(x.nama_suami||'').trim(),String(x.nama_istri||'').trim()].join('|')}
function announcementURL(x){const u=new URL(window.location.href);u.hash='informasi?nikah='+encodeURIComponent(announcementKey(x));return u.href}
function announcementFromLink(){const params=new URLSearchParams(location.hash.split('?')[1]||'');const key=params.get('nikah');if(!key||annStatus!=='ready')return;const idx=announcements.findIndex(x=>announcementKey(x)===key);if(idx>=0)openAnnouncement(idx)}
async function copyAnnouncementLink(url){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(url)}else{const field=document.createElement('textarea');field.value=url;field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();const ok=document.execCommand('copy');field.remove();if(!ok)throw Error('Salin gagal')}alert('Tautan pengumuman berhasil disalin.')}catch{window.prompt('Salin tautan pengumuman berikut:',url)}}
async function shareAnnouncement(i){const x=announcements[i];if(!x)return;const url=announcementURL(x);const title='Pengumuman kehendak nikah — KUA Cipeundeuy';const text=`Pengumuman kehendak nikah: ${x.nama_suami} dan ${x.nama_istri}.`;if(navigator.share){try{await navigator.share({title,text,url});return}catch(e){if(e.name==='AbortError')return}}await copyAnnouncementLink(url)}
function openAnnouncement(i){const x=announcements[i];if(!x)return;openDialog(`<span class="eyebrow">PENGUMUMAN KEHENDAK NIKAH</span><h2 id="dialogTitle">Rencana akad nikah</h2><div class="couple">${[[x.foto_suami_url,x.nama_suami,'Calon suami'],[x.foto_istri_url,x.nama_istri,'Calon istri']].map(v=>`<div>${v[0]?`<img src="${safeURL(v[0])}" alt="${esc(v[2])}">`:''}<h3>${esc(v[1])}</h3><small>${v[2]}</small></div>`).join('')}</div><div class="dialog-meta"><strong>${fmtDate(x.tanggal_akad,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</strong><p>${esc(x.alamat_akad||'Lokasi dikonfirmasikan melalui petugas.')}</p></div><p style="font-size:11px;margin-top:18px">Untuk konfirmasi atau informasi terkait pengumuman, hubungi petugas KUA melalui kanal resmi.</p><div class="dialog-actions"><button type="button" class="button" data-share-announcement="${i}">Bagikan pengumuman</button><button type="button" class="button outline" data-copy-announcement="${i}">Salin tautan</button>${external(wa,'Hubungi petugas')}</div>`)}
async function loadAnnouncements(){annStatus='loading';refreshAnnouncements();try{const rows=await api('pengumuman_nikah','select=nama_suami,nama_istri,tanggal_akad,alamat_akad,status,mode_publikasi,foto_suami_url,foto_istri_url&order=tanggal_akad.asc');const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(x=>x.type===t).value;const today=Date.parse(`${get('year')}-${get('month')}-${get('day')}T00:00:00Z`);announcements=rows.filter(x=>{if(x.status==='Selesai'||x.mode_publikasi==='Sembunyikan'||!x.foto_suami_url||!x.foto_istri_url)return false;const date=String(x.tanggal_akad||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return false;const diff=(Date.parse(date+'T00:00:00Z')-today)/86400000;return diff>=0&&(x.mode_publikasi==='Tampilkan sekarang'||diff<=7)});annStatus='ready'}catch{annStatus='error'}refreshAnnouncements();announcementFromLink()}
function refreshAnnouncements(){const h=document.getElementById('homeAnnouncements'),a=document.getElementById('allAnnouncements');if(h)h.innerHTML=announcementMarkup(2);if(a)a.innerHTML=announcementMarkup()}
async function loadStats(){if(statsState==='loading')return;statsState='loading';updateStatsViews();const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),14000);try{const response=await fetch(API+'/rest/v1/rpc/sand_arsip_statistik_public',{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':'application/json'},body:'{}',signal:ctrl.signal});if(!response.ok)throw Error('Statistik belum tersedia');const payload=await response.json();if(!payload||typeof payload!=='object'||!Array.isArray(payload.per_tahun)||!Number.isFinite(Number(payload.total_arsip)))throw Error('Format statistik tidak valid');const result={};for(const row of payload.per_tahun){const year=Number(row.tahun),count=Number(row.jumlah);if(Number.isInteger(year)&&year>0&&Number.isFinite(count)&&count>=0)result[year]=count;}stats=result;statsTotal=Number(payload.total_arsip);statsUpdated=new Date();statsState='ready';}catch{statsState='error';}finally{clearTimeout(timer);updateStatsViews();}}
function updateStatsViews(){const full=document.getElementById('statsContent'),home=document.getElementById('homeStatsContent');if(full)full.innerHTML=statsContent();if(home)home.innerHTML=homeStatsMarkup();}
main.addEventListener('click',e=>{const filter=e.target.closest('[data-service-category]');if(filter){serviceCategory=filter.dataset.serviceCategory;document.querySelectorAll('[data-service-category]').forEach(b=>{b.classList.toggle('active',b.dataset.serviceCategory===serviceCategory);b.setAttribute('aria-pressed',b.dataset.serviceCategory===serviceCategory)});updateCatalog();return;}const jump=e.target.closest('[data-jump]');if(jump){e.preventDefault();document.getElementById(jump.dataset.jump)?.scrollIntoView({behavior:'smooth'});return;}const b=e.target.closest('[data-service],[data-announcement],[data-retry]');if(!b)return;if(b.dataset.service)openService(b.dataset.service);if(b.dataset.announcement!==undefined)openAnnouncement(Number(b.dataset.announcement));if(b.dataset.retry==='announcements')loadAnnouncements();if(b.dataset.retry==='stats')loadStats()});
main.addEventListener('input',e=>{if(e.target.matches('[data-doc-check]')){const count=document.querySelectorAll('[data-doc-check]:checked').length;document.getElementById('checkProgress').textContent=count+' dari '+document.querySelectorAll('[data-doc-check]').length+' berkas sudah diperiksa';return;}if(e.target.id==='serviceSearch'){serviceQuery=e.target.value;updateCatalog()}});
dialog.addEventListener('click',e=>{const share=e.target.closest('[data-share-announcement]');if(share){shareAnnouncement(Number(share.dataset.shareAnnouncement));return}const copy=e.target.closest('[data-copy-announcement]');if(copy){const x=announcements[Number(copy.dataset.copyAnnouncement)];if(x)copyAnnouncementLink(announcementURL(x));return}if(e.target.closest('[data-close-service]'))dialog.close()});document.getElementById('closeDialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{const v=dialog.querySelector('video');if(v)v.pause()});
document.querySelector('.menu-toggle').onclick=()=>{const m=document.getElementById('mobileMenu');m.hidden=!m.hidden;document.querySelector('.menu-toggle').setAttribute('aria-expanded',!m.hidden)};document.getElementById('mobileMenu').addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();render();announcementFromLink()});document.getElementById('year').textContent=new Date().getFullYear();hydrateIcons();
await loadWebsiteSettings();wa='https://wa.me/'+websiteContent().contact.whatsapp;for(const [id,v]of Object.entries(websiteContent().services)){const item=services.find(x=>x.id===id);if(item)item.desc=v.desc;}applyWebsiteContent(document);
try{const r=await fetch('./data.json');if(r.ok)data=await r.json()}catch{}render(false);loadAnnouncements();
// Public records only; no archive names, identifiers, or admin records are requested.
for(const [table,query] of [['pegawai_kua','select=nama,jabatan,foto_url,urutan,aktif&aktif=eq.true&order=urutan.asc'],['kepala_kua','select=nama,masa,keterangan,foto_url,urutan&aktif=eq.true&order=urutan.asc']]){api(table,query).then(rows=>{data[table]=rows;if(table==='pegawai_kua'&&route==='pegawai')document.getElementById('employeeGrid').innerHTML=peopleMarkup(rows);if(table==='kepala_kua'&&route==='profil')document.getElementById('leadershipGrid').innerHTML=leadershipMarkup();}).catch(()=>{})}

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView()});

// Tombol mengambang mengikuti layar tanpa mengubah rute halaman.
const backTop=document.querySelector('.back-to-top');
if(backTop){
 const updateBackTop=()=>{backTop.hidden=window.scrollY<320;};
 let backTopFrame=false;
 const scheduleBackTop=()=>{if(backTopFrame)return;backTopFrame=true;requestAnimationFrame(()=>{backTopFrame=false;updateBackTop();});};
 window.addEventListener('scroll',scheduleBackTop,{passive:true});
 window.addEventListener('pageshow',updateBackTop);
 window.addEventListener('hashchange',scheduleBackTop);
 backTop.addEventListener('click',()=>{
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  main.focus({preventScroll:true});
  window.scrollTo({top:0,behavior:reduced?'instant':'smooth'});
 });
 updateBackTop();
}
